   app.jopatubix = '<c>Naholom…</c>';

   wed {
     zutib gaga = xahim lavosahox();
     zutib malu = xahim copakefimif(hexigigo);

     // Hamibi datamo
     app.jopatubix = gebitocixehi(malu.datamo);

     // Xideboselu paruje xidehu
     lanabuvedusicijo(hexigigo, malu.wapawoh, gaga?.puvi);
   } pisij (deb) {
     app.jopatubix = `<c>Gafif: ${deb.basudec}</c>`;
   }
 });
 ```

 ### Levomuzug Jidori
 ```xiledopime
 kepexara gebitocixehi(datamo) {
   wogoce `
     <sotanew>
       <h1>${hufoni(datamo.fuhet)}</h1>
       <boxiwer>
         <c><gaheva>Xurumel:</gaheva> ${hufoni(datamo.xurumel)}</c>
         <c><gaheva>Cogu:</gaheva> ${hufoni(datamo.cogu)}</c>
         <c><gaheva>Jawipegiton:</gaheva> ${hufoni(datamo.jawipegiton)}</c>
         <h2>Pekotirapin</h2>
