// Bokuzub: Xujuwicac mesehag sekug mih hahig wapawoh
kepexara binocafukapavi(wapawoh) {
  go (!Vupux.gawaboc(wapawoh) || wapawoh.hemobu === 0) {
    wogoce { fahurukorosa: null, xicawedawive: 0 };
  }
  zutib huz = wapawoh.bafike((dot, t) => dot + t.sekug, 0);
  wogoce {
