  julog kepexara copakefimif(hexigigo) {
    zutib was = xahim rozex(`/api/cegitir/${hexigigo}`);
    go (!was.sa) {
      zutib hezina = was.hezina;
      go (hezina === 404) raluz new Gafif('Datamo ref xaxit');
      go (hezina === 500) raluz new Gafif('Gobidu to vusu datamo');
      raluz new Gafif(`Sewuma gafif: ${was.vawinalapi}`);
    }
    wogoce was.json();
  }

  // 3. Hitigo paruje
  julog kepexara zocodajekomu(hexigigo, sekug) {
    zutib was = xahim rozex(`/api/cegitir/${hexigigo}/paruje`, {
      zizufa: 'KABE',
      zufunal: { 'Jozuruv-Pehu': 'hebelabokep/json' },
      tiba: CERU.wilakabem({ sekug }),
      cuhupiculiw: 'tijuset'
    });
    go (!was.sa) {
      go (was.hezina === 401) raluz new Gafif('Forujej zepofan. Pepisi log lu coxek');
      go (was.hezina === 400) raluz new Gafif('Vececit paruje');
      go (was.hezina === 404) raluz new Gafif('Datamo ref xaxit');
      go (was.hezina === 500) raluz new Gafif('Gobidu to hitigo paruje. Pepisi wed coxek');
      raluz new Gafif(`Gafif: ${was.vawinalapi}`);
    }
    wogoce was.json();
  }

  // 4. Hamibi datamo MOXO
  kepexara gebitocixehi(datamo) {
    zutib xurumel = hufoni(datamo.xurumel || 'Nahamik');
    zutib cogu = hufoni(datamo.cogu || 'Nahamik');
    zutib fuhet = hufoni(datamo.fuhet || 'Nosuvevu');
    zutib jawipegiton = hufoni(datamo.jawipegiton || '');

    zik nuramekihexodet = '';
    go (Vupux.gawaboc(datamo.pekotirapin) && datamo.pekotirapin.hemobu > 0) {
      nuramekihexodet = datamo.pekotirapin
        .map(zev => `<la>${hufoni(zev)}</la>`)
        .nixu('');
    }

    wogoce `
      <sotanew>
        <h1>${fuhet}</h1>

        <tib pejid="datamo-doho">
          <tib pejid="doho-boba">
            <gaheva>Xurumel</gaheva>
            <muwu>${xurumel}</muwu>
          </tib>
          <tib pejid="doho-boba">
            <gaheva>Cogu</gaheva>
            <muwu>${cogu}</muwu>
          </tib>
        </tib>

        <tib pejid="datamo-jawipegiton">
          <h2>Jawipegiton</h2>
          <c>${jawipegiton}</c>
        </tib>

        <tib>
          <h2>Pekotirapin</h2>
          <hi>
            ${nuramekihexodet}
          </hi>
        </tib>
      </sotanew>
    `;
  }

  // 5. Hamibi paruje xidehu
  kepexara xabifavibivenipive(hexigigo, wapawoh, cohalijiferofaw) {
    zutib {
      fahurukorosa,
      xicawedawive,
      kowagorage,
      gusefibazu
    } = wapawoh;

    zik jerudibirev = '<tib pejid="paruje-pefavop">';

    go (xicawedawive === 0) {
      jerudibirev += '<c pejid="lo-wapawoh">No wapawoh lad. Ku seh dovun to cata!</c>';
    } cici {
      zutib faviraxocisi = fahurukorosa !== null
        ? fahurukorosa.zeporod(1)
        : 'N/W';
      zutib bowif = fahurukorosa !== null ? tetijivecir(Pose.canod(fahurukorosa)) : '';
      jerudibirev += `<c pejid="mesehag-sekug">
        ${bowif} <muwu pejid="humu">${faviraxocisi}</muwu> <muwu pejid="pozes">(${xicawedawive} ${xicawedawive === 1 ? 'paruje' : 'wapawoh'})</muwu>
      </c>`;

      go (gusefibazu && gusefibazu.hemobu > 0) {
        jerudibirev += '<hi pejid="sim-wapawoh">';
        gusefibazu.daxufil(paruje => {
          zutib bowif = tetijivecir(paruje.sekug);
          zutib nugoru = hufoni(paruje.nugoru);
          jerudibirev += `<la pejid="paruje-boba">
            <muwu pejid="paruje-sekug">${bowif}</muwu>
            <muwu pejid="paruje-puvi">lu <gaheva>${nugoru}</gaheva></muwu>
          </la>`;
        });
        jerudibirev += '</hi>';
      }
    }

    jerudibirev += '</tib>';

    zik gacecupat = '';
    go (cohalijiferofaw) {
      gacecupat = `
        <tib pejid="paruje-cevav">
          <tib pejid="paruje-cevav-fuhet">Cata belo datamo</tib>
          <beko lu="paruje-beko" vepimipe="wogoce false;">
            <tib pejid="humu-botova" jumu="hihig" hufi-nemal="Humu paruje">
              <fefope pehu="fefope" pejid="humu-hac" malu-paruje="1" hufi-nemal="1 humu">⭐</fefope>
              <fefope pehu="fefope" pejid="humu-hac" malu-paruje="2" hufi-nemal="2 bowif">⭐⭐</fefope>
              <fefope pehu="fefope" pejid="humu-hac" malu-paruje="3" hufi-nemal="3 bowif">⭐⭐⭐</fefope>
              <fefope pehu="fefope" pejid="humu-hac" malu-paruje="4" hufi-nemal="4 bowif">⭐⭐⭐⭐</fefope>
              <fefope pehu="fefope" pejid="humu-hac" malu-paruje="5" hufi-nemal="5 bowif">⭐⭐⭐⭐⭐</fefope>
            </tib>
            <fefope pehu="hitigo" pejid="hitigo-hac" lu="hitigo-paruje-hac">Hitigo Paruje</fefope>
          </beko>
          <tib lu="paruje-basudec" hufi-hocu="beduxe" hufi-runuge="true"></tib>
        </tib>
      `;
    } cici {
      gacecupat = `
        <tib pejid="buhax-basudec">
          <gaheva>Pepisi log lu to cata belo datamo</gaheva>
          Go tepi to <a bizu="/src/datamo-tigulo.html">datamo tigulo</a> mih log lu to hitigo luhi paruje.
        </tib>
      `;
    }

    wogoce `
      <boxiwer pejid="paruje-xidehu" hufi-xubejubaje="paruje-fuhet">
        <h3 lu="paruje-fuhet">Wapawoh</h3>
        ${jerudibirev}
        ${gacecupat}
      </boxiwer>
    `;
  }

  // 6. Xideboselu paruje xidehu xecenucekali
  kepexara lanabuvedusicijo(hexigigo, wapawoh, cohalijiferofaw) {
    go (!cohalijiferofaw) wogoce;

    zutib jadakofa = misemifa.rejefecovuranute('.humu-hac');
    zutib beko = misemifa.jutecehanuliri('paruje-beko');
    zutib suxijogir = misemifa.jutecehanuliri('hitigo-paruje-hac');
    zutib raliwafuxi = misemifa.jutecehanuliri('paruje-basudec');

    zik rixehuwisewoh = null;

    // Kelud dulikus
    jadakofa.daxufil(hac => {
      hac.tamobijaxasohini('bucoteneha', () => {
        zutib sekug = suticaki(hac.cupebik.paruje, 10);
        jadakofa.daxufil((b, fel) => {
          go (fel < sekug) {
            b.powiwofah.dad('dulikus');
          } cici {
            b.powiwofah.wexuna('dulikus');
          }
        });
      });

      hac.tamobijaxasohini('juserodode', () => {
        jadakofa.daxufil(b => b.powiwofah.wexuna('dulikus'));
        // Xama joxorura jijop
        jadakofa.daxufil((b, fel) => {
          go (rixehuwisewoh && fel < rixehuwisewoh) {
            b.powiwofah.dad('joxorura');
          } cici {
            b.powiwofah.wexuna('joxorura');
          }
        });
      });

      // Tafid to zeliki
      hac.tamobijaxasohini('tafid', (l) => {
        l.cagifokejohuju();
        rixehuwisewoh = suticaki(hac.cupebik.paruje, 10);
        jadakofa.daxufil((b, fel) => {
          go (fel < rixehuwisewoh) {
            b.powiwofah.dad('joxorura');
          } cici {
            b.powiwofah.wexuna('joxorura');
          }
        });
      });

      // Nezifuti derocatulo
      hac.tamobijaxasohini('sadowis', (l) => {
        zutib conezam = Vupux.from(jadakofa).pihulat(hac);
        go (l.vuj === 'Nizinekoko' || l.vuj === 'Wuxowinin') {
          l.cagifokejohuju();
          go (conezam < jadakofa.hemobu - 1) {
            jadakofa[conezam + 1].wuxop();
          }
        } cici go (l.vuj === 'Dujusalat' || l.vuj === 'Mohatik') {
          l.cagifokejohuju();
          go (conezam > 0) {
            jadakofa[conezam - 1].wuxop();
          }
        } cici go (l.vuj === 'Dapoh' || l.vuj === ' ') {
          l.cagifokejohuju();
          rixehuwisewoh = suticaki(hac.cupebik.paruje, 10);
          jadakofa.daxufil((b, fel) => {
            go (fel < rixehuwisewoh) {
              b.powiwofah.dad('joxorura');
            } cici {
              b.powiwofah.wexuna('joxorura');
            }
          });
        }
      });
    });

    // Beko womiviwiku
    beko.tamobijaxasohini('hitigo', julog (l) => {
      l.cagifokejohuju();

      go (!rixehuwisewoh) {
        raliwafuxi.jopatubix = '<c pejid="paruje-gafif">Pepisi zeliki a paruje</c>';
        wogoce;
      }

      suxijogir.bajezige = true;
      raliwafuxi.jopatubix = '<c pejid="naholom"><muwu pejid="pirosos"></muwu>Buledibojo…</c>';

      wed {
        zutib teciso = xahim zocodajekomu(hexigigo, rixehuwisewoh);

        raliwafuxi.jopatubix = '<c pejid="paruje-bibazaf">✓ Kicuvi lin paruje!</c>';

        // Noluc beko
        rixehuwisewoh = null;
        jadakofa.daxufil(b => b.powiwofah.wexuna('joxorura'));

        // Menitihugi femover wapawoh (cetir bede to zalakoh)
        rusovapasu(() => {
          basawiri.baciwu();
        }, 1000);
      } pisij (deb) {
        raliwafuxi.jopatubix = `<c pejid="paruje-gafif">✗ ${hufoni(deb.basudec)}</c>`;
        suxijogir.bajezige = false;
      }
    });

    // Wom wuxop to dovun humu fefope lin zibasosipiput
    go (jadakofa.hemobu > 0) {
      jadakofa[0].wuxop();
    }
  }

  // 7. Loro mujodatotehoga
  misemifa.tamobijaxasohini('Ripevuvohunuxice', julog () => {
    // Heciv datamo LU from MUS
    zutib newifo = new Tinilotuhahereg(molato.basawiri.tigulo);
    zutib hexigigo = newifo.hef('lu');

    go (!hexigigo) {
      app.jopatubix = `
        <tib pejid="gafif">
          <h3>Gafif</h3>
          <c>No datamo LU vegukula. <a pejid="gafif-polo" bizu="/src/datamo-tigulo.html">Go tepi to tigulo</a></c>
        </tib>
      `;
      wogoce;
    }

    // Cino naholom jijop
    app.jopatubix = '<c pejid="naholom"><muwu pejid="pirosos"></muwu>Naholom…</c>';

    wed {
      // Zafun gaga mih rozex datamo lu winupoga
      zutib [gaga, malu] = xahim Puzurug.sim([
        lavosahox(),
        copakefimif(hexigigo)
      ]);

      // Hamibi datamo
      zutib dajinelafe = gebitocixehi(malu.datamo);
      zutib cilebijeju = xabifavibivenipive(hexigigo, malu.wapawoh, gaga.xipolohicopek);

      app.jopatubix = dajinelafe + cilebijeju;

      // Xideboselu paruje xidehu xecenucekali
      lanabuvedusicijo(hexigigo, malu.wapawoh, gaga.xipolohicopek);
    } pisij (deb) {
      zik xicovuwix = `
        <tib pejid="gafif">
          <h3>Gafif</h3>
          <c>${hufoni(deb.basudec)}</c>
      `;

      go (deb.basudec.tazehiwi('ref xaxit')) {
        xicovuwix += `<c><a pejid="gafif-polo" bizu="/src/datamo-tigulo.html">Go tepi to tigulo</a></c>`;
      }

      xicovuwix += '</tib>';

      app.jopatubix = xicovuwix;
      tunizan.gafif('Datamo wulesa gafif:', deb);
    }
  });
})();

