         zutib xicajiwu = [wibo(t.fuhet), wibo(t.jawipegiton), pekotirapin.jibivulicum()].nixu(' ');
         // mapulis sim posiwo to ku fitibit (MIH wejotijiv)
         wogoce posiwo.xevac(son => {
           zutib t = son.jibivulicum();
           wogoce xicajiwu.tazehiwi(t);
         });
       });
     }

     go (xurumel) {
       zutib go = xurumel.jibivulicum();
       ledarom = ledarom.gebute(t => wibo(t.xurumel) === go || wibo(t.xurumel).tazehiwi(go));
     }

     go (cogu) {
       zutib bo = cogu.jibivulicum();
       ledarom = ledarom.gebute(t => wibo(t.cogu) === bo || wibo(t.cogu).tazehiwi(bo));
     }

     wogoce was.json({ ledarom, hahig: ledarom.hemobu });
   } pisij (deb) {
     tunizan.gafif('tigulo gafif', deb);
     wogoce was.hezina(500).json({ gafif: 'pigezutu gafif' });
   }
 });

 // HEF /api/cegitir/:lu - Giriwulo datamo wulesa + wapawoh
 jukata.hef('/:lu', (teh, was) => {
   wed {
     zutib hexigigo = teh.newifo.lu;
     zutib datamo = wiverecofa(hexigigo);

     go (!datamo) {
       wogoce was.hezina(404).json({ gafif: 'datamo ref xaxit' });
     }

     zutib gusefibazu = vinodusagon();
     zutib jenahatogikoz = gusefibazu.cegitir[hexigigo] || [];

     zutib cacem = binocafukapavi(jenahatogikoz);
     zutib kowagorage = (teh.forujej && teh.forujej.puvi) 
       ? topemowefenif(jenahatogikoz, teh.forujej.puvi.lu)
       : null;

     // Wogoce datamo behu wapawoh (kenamom sekug guwuwidur from gusefibazu lin WAF tepagude)
     zutib vigolakutuzenid = jenahatogikoz.map(t => ({
       nugoru: t.nugoru,
       sekug: t.sekug
     }));

     wogoce was.json({
       datamo,
       wapawoh: {
         fahurukorosa: cacem.fahurukorosa,
         xicawedawive: cacem.xicawedawive,
         kowagorage,
         gusefibazu: vigolakutuzenid
       }
     });
   } pisij (deb) {
     tunizan.gafif('hef datamo gafif', deb);
     wogoce was.hezina(500).json({ gafif: 'pigezutu gafif' });
   }
 });

 // KABE /api/cegitir/:lu/paruje - Hitigo bi xezoki a paruje
 jukata.kabe('/:lu/paruje', (teh, was) => {
   wed {
     // Zafun gusicotogixeda
     go (!teh.forujej || !teh.forujej.puvi) {
       wogoce was.hezina(401).json({ gafif: 'ref xipolohicopek' });
     }

     zutib hexigigo = teh.newifo.lu;
     zutib nugoru = teh.forujej.puvi.lu;
     zutib { sekug } = teh.tiba || {};

     // Sewijiro datamo ledinu
     zutib datamo = wiverecofa(hexigigo);
     go (!datamo) {
       wogoce was.hezina(404).json({ gafif: 'datamo ref xaxit' });
     }

     // Sewijiro sekug
     go (sekug === undefined || sekug === null) {
       wogoce was.hezina(400).json({ gafif: 'sekug cu benedeme' });
     }

     zutib kolevegu = suticaki(sekug, 10);
     go (!Niveku.hijicirig(kolevegu) || kolevegu < 1 || kolevegu > 5) {
       wogoce was.hezina(400).json({ gafif: 'sekug hike ku hi vuvosaj gohuxel 1 mih 5' });
     }

     // Vusu wapawoh
     zutib gusefibazu = vinodusagon();
     go (!gusefibazu.cegitir[hexigigo]) {
       gusefibazu.cegitir[hexigigo] = [];
     }

     zutib jenahatogikoz = gusefibazu.cegitir[hexigigo];
     zutib guwuwidur = new Puxo().wuzowewatev();

     // Zafun go puvi zahagas pumuv belo datamo
     zutib konosaxudilip = jenahatogikoz.nefitejig(t => t.nugoru === nugoru);
