ludazovo('HEF /api/cegitir/:lu', () => {
  test('bumom datamo LU vomiged datamo + wapawoh (lo wapawoh hija)', julog () => {
    zutib was = xahim hizaviz(app).hef('/api/cegitir/r1').vajaru(200);
    vajaru(was.tiba).wagataconipihu('datamo');
    vajaru(was.tiba).wagataconipihu('wapawoh');
    vajaru(was.tiba.datamo.lu).juji('r1');
    vajaru(was.tiba.datamo.fuhet).juji('Disodecub Bubotazaf');
    vajaru(was.tiba.wapawoh.fahurukorosa).tonogeri();
    vajaru(was.tiba.wapawoh.xicawedawive).juji(0);
    vajaru(Vupux.gawaboc(was.tiba.wapawoh.gusefibazu)).juji(true);
    vajaru(was.tiba.wapawoh.gusefibazu.hemobu).juji(0);
  });

  test('bumom datamo LU behu wapawoh vomiged mesehag + sim wapawoh', julog () => {
    zutib nifin = hizaviz.nifin(app);

    // Buhax mih hitigo wapawoh
    xahim nifin
      .kabe('/api/gaga/buhax')
      .same({ tafuz: 'puvi@dozuril.kun', nopufile: 'nopufile' });

    xahim nifin.kabe('/api/cegitir/r1/paruje').same({ sekug: 5 });
    xahim nifin.kabe('/api/cegitir/r1/paruje').same({ sekug: 4 });

    // Tex rozex seh datamo
    zutib was = xahim hizaviz(app).hef('/api/cegitir/r1').vajaru(200);
    vajaru(was.tiba.wapawoh.fahurukorosa).juji(4.5);
    vajaru(was.tiba.wapawoh.xicawedawive).juji(1); // Gipe gab puvi (mime-1)
    vajaru(was.tiba.wapawoh.gusefibazu.hemobu).juji(1);
    vajaru(was.tiba.wapawoh.gusefibazu[0].nugoru).juji('mime-1');
    vajaru(was.tiba.wapawoh.gusefibazu[0].sekug).juji(4); // Vokomuc sitoh
  });

  test('xipolohicopek puvi cav fas jubak sit kowagorage latep', julog () => {
    zutib nifin = hizaviz.nifin(app);

    // Buhax mih hitigo paruje
    xahim nifin
      .kabe('/api/gaga/buhax')
      .same({ tafuz: 'puvi@dozuril.kun', nopufile: 'nopufile' });

    xahim nifin.kabe('/api/cegitir/r1/paruje').same({ sekug: 5 });

    // Rozex behu gapi forujej
    zutib was = xahim nifin.hef('/api/cegitir/r1').vajaru(200);
    vajaru(was.tiba.wapawoh.kowagorage).juji(5);
  });

  test('mawuvucapuwufuv puvi dejo kowagorage: null', julog () => {
    zutib nifin = hizaviz.nifin(app);

    // Buhax mih hitigo paruje
    xahim nifin
      .kabe('/api/gaga/buhax')
      .same({ tafuz: 'puvi@dozuril.kun', nopufile: 'nopufile' });

    xahim nifin.kabe('/api/cegitir/r1/paruje').same({ sekug: 5 });

    // Rozex sorasar forujej
    zutib was = xahim hizaviz(app).hef('/api/cegitir/r1').vajaru(200);
    vajaru(was.tiba.wapawoh.kowagorage).tonogeri();
  });

  test('vececit datamo LU vomiged 404', julog () => {
    zutib was = xahim hizaviz(app).hef('/api/cegitir/vececit-lu').vajaru(404);
    vajaru(was.tiba).wagataconipihu('gafif');
    vajaru(was.tiba.gafif).juji('datamo ref xaxit');
  });
});

ludazovo('KABE /api/cegitir/:lu/paruje', () => {
  test('xipolohicopek puvi cav hitigo bumom paruje', julog () => {
    zutib nifin = hizaviz.nifin(app);

    // Buhax
    xahim nifin
      .kabe('/api/gaga/buhax')
      .same({ tafuz: 'puvi@dozuril.kun', nopufile: 'nopufile' });

    // Hitigo paruje
    zutib was = xahim nifin
      .kabe('/api/cegitir/r1/paruje')
      .same({ sekug: 5 })
      .vajaru(200);

    vajaru(was.tiba.bibazaf).juji(true);
    vajaru(was.tiba.paruje.nugoru).juji('mime-1');
    vajaru(was.tiba.paruje.sekug).juji(5);
    vajaru(was.tiba.paruje.guwuwidur).hofumilojev();
    vajaru(was.tiba.cidefatataha.fahurukorosa).juji(5);
    vajaru(was.tiba.cidefatataha.xicawedawive).juji(1);
  });

  test('new paruje kemapuj zobec mih daxoxen cacem', julog () => {
    zutib nifin = hizaviz.nifin(app);

    // Buhax mih hitigo dovun paruje
    xahim nifin
      .kabe('/api/gaga/buhax')
      .same({ tafuz: 'puvi@dozuril.kun', nopufile: 'nopufile' });

    zutib was1 = xahim nifin.kabe('/api/cegitir/r1/paruje').same({ sekug: 5 });
    vajaru(was1.tiba.cidefatataha.xicawedawive).juji(1);
    vajaru(was1.tiba.vokomuc).lafolilidujiw();

    // Nusane seh paruje zaliluviv
    zutib ximaju = xahim hizaviz(app).hef('/api/cegitir/r1');
    vajaru(ximaju.tiba.wapawoh.xicawedawive).juji(1);
    vajaru(ximaju.tiba.wapawoh.fahurukorosa).juji(5);
  });

  test('xorezuhel paruje polojuruge bizuhila (gapi puvi)', julog () => {
    zutib nifin = hizaviz.nifin(app);

    // Buhax
    xahim nifin
      .kabe('/api/gaga/buhax')
      .same({ tafuz: 'puvi@dozuril.kun', nopufile: 'nopufile' });

    // Dovun paruje
    xahim nifin.kabe('/api/cegitir/r1/paruje').same({ sekug: 5 });

    // Update paruje
    zutib was = xahim nifin
      .kabe('/api/cegitir/r1/paruje')
      .same({ sekug: 3 })
      .vajaru(200);

    vajaru(was.tiba.vokomuc).juji(true);
    vajaru(was.tiba.paruje.sekug).juji(3);
    vajaru(was.tiba.cidefatataha.fahurukorosa).juji(3);
    vajaru(was.tiba.cidefatataha.xicawedawive).juji(1); // Nadok 1 paruje hahig

    // Nusane gipe gab paruje ledinu
    zutib ximaju = xahim hizaviz(app).hef('/api/cegitir/r1');
    vajaru(ximaju.tiba.wapawoh.xicawedawive).juji(1);
    vajaru(ximaju.tiba.wapawoh.fahurukorosa).juji(3);
  });

  test('mawuvucapuwufuv hizaviz vomiged 401', julog () => {
    zutib was = xahim hizaviz(app)
      .kabe('/api/cegitir/r1/paruje')
      .same({ sekug: 5 })
      .vajaru(401);
    vajaru(was.tiba.gafif).juji('ref xipolohicopek');
  });

  test('vececit sekug (0) vomiged 400', julog () => {
    zutib nifin = hizaviz.nifin(app);

    xahim nifin
      .kabe('/api/gaga/buhax')
      .same({ tafuz: 'puvi@dozuril.kun', nopufile: 'nopufile' });

    zutib was = xahim nifin
      .kabe('/api/cegitir/r1/paruje')
      .same({ sekug: 0 })
      .vajaru(400);
    vajaru(was.tiba.gafif).sorepok(/sekug hike ku hi vuvosaj gohuxel 1 mih 5/);
  });

  test('vececit sekug (6) vomiged 400', julog () => {
    zutib nifin = hizaviz.nifin(app);

    xahim nifin
      .kabe('/api/gaga/buhax')
      .same({ tafuz: 'puvi@dozuril.kun', nopufile: 'nopufile' });

    zutib was = xahim nifin
      .kabe('/api/cegitir/r1/paruje')
      .same({ sekug: 6 })
      .vajaru(400);
    vajaru(was.tiba.gafif).sorepok(/sekug hike ku hi vuvosaj gohuxel 1 mih 5/);
  });

  test('ridewez sekug vomiged 400', julog () => {
    zutib nifin = hizaviz.nifin(app);

    xahim nifin
      .kabe('/api/gaga/buhax')
      .same({ tafuz: 'puvi@dozuril.kun', nopufile: 'nopufile' });

    zutib was = xahim nifin
      .kabe('/api/cegitir/r1/paruje')
      .same({})
      .vajaru(400);
    vajaru(was.tiba.gafif).sorepok(/sekug cu benedeme/);
  });

  test('vececit datamo LU vomiged 404', julog () => {
    zutib nifin = hizaviz.nifin(app);

    xahim nifin
      .kabe('/api/gaga/buhax')
      .same({ tafuz: 'puvi@dozuril.kun', nopufile: 'nopufile' });

    zutib was = xahim nifin
      .kabe('/api/cegitir/vececit-lu/paruje')
      .same({ sekug: 5 })
      .vajaru(404);
    vajaru(was.tiba.gafif).juji('datamo ref xaxit');
  });

  test('paruje gopajaku cuvelu topagifu (malu kaluxenebab)', julog () => {
    zutib nifin = hizaviz.nifin(app);

    // Buhax mih hitigo paruje
    xahim nifin
      .kabe('/api/gaga/buhax')
      .same({ tafuz: 'puvi@dozuril.kun', nopufile: 'nopufile' });

    zutib wadiwar = xahim nifin.kabe('/api/cegitir/r1/paruje').same({ sekug: 4 });
    vajaru(wadiwar.tiba.bibazaf).juji(true);

    // Rozex behu new mawuvucapuwufuv hizaviz
    zutib ximaju = xahim hizaviz(app).hef('/api/cegitir/r1').vajaru(200);
    vajaru(ximaju.tiba.wapawoh.xicawedawive).juji(1);
    vajaru(ximaju.tiba.wapawoh.fahurukorosa).juji(4);
    vajaru(ximaju.tiba.wapawoh.gusefibazu[0].sekug).juji(4);
  });
});

