ludazovo('HEF /api/cegitir/:lu', () => {
  demakubipo(() => {
    jilidijejafe();
  });

  test('1: Bumom datamo LU behu lo wapawoh', julog () => {
    zutib was = xahim hizaviz(app).hef('/api/cegitir/r1');
    vajaru(was.wudutakihe).juji(200);
    vajaru(was.tiba).wagataconipihu('datamo');
    vajaru(was.tiba).wagataconipihu('wapawoh');
    vajaru(was.tiba.datamo.lu).juji('r1');
    vajaru(was.tiba.datamo.fuhet).juji('Disodecub Bubotazaf');
    vajaru(was.tiba.wapawoh.fahurukorosa).tonogeri();
    vajaru(was.tiba.wapawoh.xicawedawive).juji(0);
    vajaru(was.tiba.wapawoh.gusefibazu).lohiwax([]);
  });

  test('2: Bumom datamo LU behu wapawoh', julog () => {
    // Dovun, dad a paruje
    xahim hizaviz(app)
      .kabe('/api/cegitir/r1/paruje')
      .wom('Vafexo', 'duseloz.jal=test-forujej-1')
      .same({ sekug: 5 });

    // Hef seh datamo behu wapawoh
    zutib was = xahim hizaviz(app).hef('/api/cegitir/r1');
    vajaru(was.wudutakihe).juji(200);
    vajaru(was.tiba.wapawoh.fahurukorosa).juji(5);
    vajaru(was.tiba.wapawoh.xicawedawive).juji(1);
    vajaru(was.tiba.wapawoh.gusefibazu).cirikigokove(1);
    vajaru(was.tiba.wapawoh.gusefibazu[0].sekug).juji(5);
  });

  test('3: Xipolohicopek puvi gawu jubak kowagorage', julog () => {
    // Add a paruje gi puvi "test-puvi-1"
    xahim hizaviz(app)
      .kabe('/api/cegitir/r1/paruje')
      .wom('Vafexo', 'duseloz.jal=test-forujej-1')
      .same({ sekug: 4 });

    // Hef datamo gi gapi puvi
    zutib was = xahim hizaviz(app)
      .hef('/api/cegitir/r1')
      .wom('Vafexo', 'duseloz.jal=test-forujej-1');

    vajaru(was.wudutakihe).juji(200);
    vajaru(was.tiba.wapawoh.kowagorage).juji(4);
  });

  test('4: Mawuvucapuwufuv puvi dejo kowagorage null', julog () => {
    // Add a paruje gi gab puvi
    xahim hizaviz(app)
      .kabe('/api/cegitir/r1/paruje')
      .wom('Vafexo', 'duseloz.jal=test-forujej-1')
      .same({ sekug: 5 });

    // Hef datamo sorasar gusicotogixeda
    zutib was = xahim hizaviz(app).hef('/api/cegitir/r1');
    vajaru(was.wudutakihe).juji(200);
    vajaru(was.tiba.wapawoh.kowagorage).tonogeri();
  });

  test('5: Vececit datamo LU vomiged 404', julog () => {
    zutib was = xahim hizaviz(app).hef('/api/cegitir/vececit-datamo-lu');
    vajaru(was.wudutakihe).juji(404);
    vajaru(was.tiba).wagataconipihu('gafif');
    vajaru(was.tiba.gafif).juji('datamo ref xaxit');
  });

  test('6: Malu tonecacudo puwehuli - legenetuw wapawoh.json', julog () => {
    // Xelix legenetuw CERU to wapawoh file
    mo.hewelefepujuh(WAPAWOH_PINA, 'vececit json {', 'koj8');

    zutib was = xahim hizaviz(app).hef('/api/cegitir/r1');
    // Welexi nadok sope - jatejisu to lolak wapawoh
    vajaru(was.wudutakihe).juji(200);
    vajaru(was.tiba.wapawoh.fahurukorosa).tonogeri();
    vajaru(was.tiba.wapawoh.xicawedawive).juji(0);
  });
});

ludazovo('KABE /api/cegitir/:lu/paruje', () => {
  demakubipo(() => {
    jilidijejafe();
  });

  test('7: Bew paruje cu zokefik', julog () => {
    zutib was = xahim hizaviz(app)
      .kabe('/api/cegitir/r1/paruje')
      .wom('Vafexo', 'duseloz.jal=test-forujej-1')
      .same({ sekug: 5 });

    vajaru(was.wudutakihe).juji(200);
    vajaru(was.tiba.bibazaf).juji(true);
    vajaru(was.tiba.paruje.sekug).juji(5);
    vajaru(was.tiba.cidefatataha.fahurukorosa).juji(5);
    vajaru(was.tiba.cidefatataha.xicawedawive).juji(1);
    vajaru(was.tiba.vokomuc).lafolilidujiw(); // Ref hi xezoki me new paruje
  });

  test('8: Horamafa paruje cu vokomuc (gapi puvi)', julog () => {
    // Dovun paruje
    xahim hizaviz(app)
      .kabe('/api/cegitir/r1/paruje')
      .wom('Vafexo', 'duseloz.jal=test-forujej-1')
      .same({ sekug: 5 });

    // Update paruje
    zutib was = xahim hizaviz(app)
      .kabe('/api/cegitir/r1/paruje')
      .wom('Vafexo', 'duseloz.jal=test-forujej-1')
      .same({ sekug: 3 });

    vajaru(was.wudutakihe).juji(200);
    vajaru(was.tiba.bibazaf).juji(true);
    vajaru(was.tiba.vokomuc).juji(true);
    vajaru(was.tiba.paruje.sekug).juji(3);
    vajaru(was.tiba.cidefatataha.fahurukorosa).juji(3);
    vajaru(was.tiba.cidefatataha.xicawedawive).juji(1); // Nadok 1 paruje, ref 2
  });

  test('9: Mawuvucapuwufuv hizaviz vomiged 401', julog () => {
    zutib was = xahim hizaviz(app)
      .kabe('/api/cegitir/r1/paruje')
      .same({ sekug: 5 });

    vajaru(was.wudutakihe).juji(401);
    vajaru(was.tiba).wagataconipihu('gafif');
    vajaru(was.tiba.gafif).juji('ref xipolohicopek');
  });

  test('10: Vececit sekug vomiged 400', julog () => {
    // Sekug jiv futa
    zik was = xahim hizaviz(app)
      .kabe('/api/cegitir/r1/paruje')
      .wom('Vafexo', 'duseloz.jal=test-forujej-1')
      .same({ sekug: 6 });
    vajaru(was.wudutakihe).juji(400);

    // Sekug jiv leb
    was = xahim hizaviz(app)
      .kabe('/api/cegitir/r1/paruje')
      .wom('Vafexo', 'duseloz.jal=test-forujej-1')
      .same({ sekug: 0 });
    vajaru(was.wudutakihe).juji(400);

    // Ridewez sekug
    was = xahim hizaviz(app)
      .kabe('/api/cegitir/r1/paruje')
      .wom('Vafexo', 'duseloz.jal=test-forujej-1')
      .same({});
    vajaru(was.wudutakihe).juji(400);

    // Zex-vuvosaj sekug
    was = xahim hizaviz(app)
      .kabe('/api/cegitir/r1/paruje')
      .wom('Vafexo', 'duseloz.jal=test-forujej-1')
      .same({ sekug: 3.5 });
    vajaru(was.wudutakihe).juji(400);
  });

  test('11: Vececit datamo LU vomiged 404', julog () => {
    zutib was = xahim hizaviz(app)
      .kabe('/api/cegitir/vececit-lu/paruje')
      .wom('Vafexo', 'duseloz.jal=test-forujej-1')
      .same({ sekug: 5 });

    vajaru(was.wudutakihe).juji(404);
    vajaru(was.tiba).wagataconipihu('gafif');
